<template><div class="credits"><div class="head"><div><h2>积分钱包</h2><p>管理 AI 获客操作的积分余额和流水。</p></div><el-button type="primary" @click="visible=true">调整积分</el-button></div><el-card class="balance"><span>当前余额</span><strong>{{ wallet.balance }}</strong><em>credits</em></el-card><el-card class="orders"><template #header>支付订单</template><el-table :data="orders"><el-table-column prop="id" label="订单号" min-width="220"/><el-table-column prop="amount" label="金额" width="100"/><el-table-column prop="provider" label="渠道" width="100"/><el-table-column prop="status" label="状态" width="110"/></el-table></el-card><el-card><template #header>积分流水</template><el-table :data="transactions"><el-table-column prop="created_at" label="时间" width="190"/><el-table-column prop="action" label="操作" width="180"/><el-table-column prop="amount" label="变动" width="120"/><el-table-column prop="balance_after" label="余额" width="120"/><el-table-column prop="description" label="说明"/></el-table></el-card><el-dialog v-model="visible" title="调整积分" width="420px"><el-form :model="form" label-width="80px"><el-form-item label="数量"><el-input-number v-model="form.amount" :min="-100000" :max="100000"/></el-form-item><el-form-item label="说明"><el-input v-model="form.description"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="adjust">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import {onMounted,reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {adjustCredits,getCreditTransactions,getWallet,getPaymentOrders,type CreditTransaction,type CreditWallet,type PaymentOrder} from '@/api/billing';const wallet=ref<CreditWallet>({id:'',user_id:'',balance:0});const transactions=ref<CreditTransaction[]>([]);const orders=ref<PaymentOrder[]>([]);const visible=ref(false);const form=reactive({amount:0,description:''});async function load(){wallet.value=await getWallet();transactions.value=await getCreditTransactions();orders.value=await getPaymentOrders()}async function adjust(){await adjustCredits({amount:form.amount,description:form.description});visible.value=false;await load();ElMessage.success('积分已调整')}onMounted(load)</script><style scoped>.credits{max-width:1200px;margin:auto}.head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:22px}.head h2{margin:0}.head p{color:#667085}.orders{margin-bottom:18px}.balance{display:flex;align-items:baseline;gap:12px;margin-bottom:18px}.balance span{color:#667085}.balance strong{font-size:42px}.balance em{color:#98a2b3;font-style:normal}</style>

